19	template <typename character>
20	static inline int
21	character_cmp(character a, character b)
22	{
23	    if (a == b) {
24	        return 0;
25	    }
26	    else if (a < b) {
27	        return -1;
28	    }
29	    else {
30	        return 1;
31	    }
32	}
