35	/*
36	 * Compare two strings of different length.  Note that either string may be
37	 * zero padded (trailing zeros are ignored in other words, the shorter word
38	 * is always padded with zeros).
39	 */
40	template <bool rstrip, typename character>
41	static inline int
42	string_cmp(int len1, const character *str1, int len2, const character *str2)
43	{
44	    if (rstrip) {
45	        /*
46	         * Ignore/"trim" trailing whitespace (and 0s).  Note that this function
47	         * does not support unicode whitespace (and never has).
48	         */
49	        while (len1 > 0) {
50	            character c = str1[len1-1];
51	            if (c != (character)0 && !NumPyOS_ascii_isspace(c)) {
52	                break;
53	            }
54	            len1--;
55	        }
56	        while (len2 > 0) {
57	            character c = str2[len2-1];
58	            if (c != (character)0 && !NumPyOS_ascii_isspace(c)) {
59	                break;
60	            }
61	            len2--;
62	        }
63	    }
64	
65	    int n = PyArray_MIN(len1, len2);
66	
67	    if (sizeof(character) == 1) {
68	        /*
69	         * TODO: `memcmp` makes things 2x faster for longer words that match
70	         *       exactly, but at least 2x slower for short or mismatching ones.
71	         */
72	        int cmp = memcmp(str1, str2, n);
73	        if (cmp != 0) {
74	            return cmp;
75	        }
76	        str1 += n;
77	        str2 += n;
78	    }
79	    else {
80	        for (int i = 0; i < n; i++) {
81	            int cmp = character_cmp(*str1, *str2);
82	            if (cmp != 0) {
83	                return cmp;
84	            }
85	            str1++;
86	            str2++;
87	        }
88	    }
89	    if (len1 > len2) {
90	        for (int i = n; i < len1; i++) {
91	            int cmp = character_cmp(*str1, (character)0);
92	            if (cmp != 0) {
93	                return cmp;
94	            }
95	            str1++;
96	        }
97	    }
98	    else if (len2 > len1) {
99	        for (int i = n; i < len2; i++) {
100	            int cmp = character_cmp((character)0, *str2);
101	            if (cmp != 0) {
102	                return cmp;
103	            }
104	            str2++;
105	        }
106	    }
107	    return 0;
108	}
