111	/*
112	 * Helper for templating, avoids warnings about uncovered switch paths.
113	 */
114	enum class COMP {
115	    EQ, NE, LT, LE, GT, GE,
116	};
117	
118	static char const *
119	comp_name(COMP comp) {
120	    switch(comp) {
121	        case COMP::EQ: return "equal";
122	        case COMP::NE: return "not_equal";
123	        case COMP::LT: return "less";
124	        case COMP::LE: return "less_equal";
125	        case COMP::GT: return "greater";
126	        case COMP::GE: return "greater_equal";
127	        default:
128	            assert(0);
129	            return nullptr;
130	    }
131	}
