217	template<bool rstrip, typename character, COMP...>
218	struct add_loops;
219	
220	template<bool rstrip, typename character>
221	struct add_loops<rstrip, character> {
222	    int operator()(PyObject*, PyArrayMethod_Spec*) {
223	        return 0;
224	    }
225	};
226	
227	template<bool rstrip, typename character, COMP comp, COMP... comps>
228	struct add_loops<rstrip, character, comp, comps...> {
229	    int operator()(PyObject* umath, PyArrayMethod_Spec* spec) {
230	        PyArrayMethod_StridedLoop* loop = string_comparison_loop<rstrip, comp, character>;
231	
232	        if (add_loop(umath, comp_name(comp), spec, loop) < 0) {
233	            return -1;
234	        }
235	        else {
236	            return add_loops<rstrip, character, comps...>()(umath, spec);
237	        }
238	    }
239	};
