242	NPY_NO_EXPORT int
243	init_string_ufuncs(PyObject *umath)
244	{
245	    int res = -1;
246	    /* NOTE: This should receive global symbols? */
247	    PyArray_DTypeMeta *String = PyArray_DTypeFromTypeNum(NPY_STRING);
248	    PyArray_DTypeMeta *Unicode = PyArray_DTypeFromTypeNum(NPY_UNICODE);
249	    PyArray_DTypeMeta *Bool = PyArray_DTypeFromTypeNum(NPY_BOOL);
250	
251	    /* We start with the string loops: */
252	    PyArray_DTypeMeta *dtypes[] = {String, String, Bool};
253	    /*
254	     * We only have one loop right now, the strided one.  The default type
255	     * resolver ensures native byte order/canonical representation.
256	     */
257	    PyType_Slot slots[] = {
258	        {NPY_METH_strided_loop, nullptr},
259	        {0, nullptr}
260	    };
261	
262	    PyArrayMethod_Spec spec = {};
263	    spec.name = "templated_string_comparison";
264	    spec.nin = 2;
265	    spec.nout = 1;
266	    spec.dtypes = dtypes;
267	    spec.slots = slots;
268	    spec.flags = NPY_METH_NO_FLOATINGPOINT_ERRORS;
269	
270	    /* All String loops */
271	    using string_looper = add_loops<false, npy_byte, COMP::EQ, COMP::NE, COMP::LT, COMP::LE, COMP::GT, COMP::GE>;
272	    if (string_looper()(umath, &spec) < 0) {
273	        goto finish;
274	    }
275	
276	    /* All Unicode loops */
277	    using ucs_looper = add_loops<false, npy_ucs4, COMP::EQ, COMP::NE, COMP::LT, COMP::LE, COMP::GT, COMP::GE>;
278	    dtypes[0] = Unicode;
279	    dtypes[1] = Unicode;
280	    if (ucs_looper()(umath, &spec) < 0) {
281	        goto finish;
282	    }
283	
284	    res = 0;
285	  finish:
286	    Py_DECREF(String);
287	    Py_DECREF(Unicode);
288	    Py_DECREF(Bool);
289	    return res;
290	}
