293	template <bool rstrip, typename character>
294	static PyArrayMethod_StridedLoop *
295	get_strided_loop(int comp)
296	{
297	    switch (comp) {
298	        case Py_EQ:
299	            return string_comparison_loop<rstrip, COMP::EQ, character>;
300	        case Py_NE:
301	            return string_comparison_loop<rstrip, COMP::NE, character>;
302	        case Py_LT:
303	            return string_comparison_loop<rstrip, COMP::LT, character>;
304	        case Py_LE:
305	            return string_comparison_loop<rstrip, COMP::LE, character>;
306	        case Py_GT:
307	            return string_comparison_loop<rstrip, COMP::GT, character>;
308	        case Py_GE:
309	            return string_comparison_loop<rstrip, COMP::GE, character>;
310	        default:
311	            assert(false);  /* caller ensures this */
312	    }
313	    return nullptr;
314	}
