/*
 * Character classification wrapper functions for use as function pointers
 * in the fast path for string classification methods.
 */
static int _npy_char_isalpha(Py_UCS4 ch) { return Py_UNICODE_ISALPHA(ch); }
static int _npy_char_isdigit(Py_UCS4 ch) { return Py_UNICODE_ISDIGIT(ch); }
static int _npy_char_isalnum(Py_UCS4 ch) { return Py_UNICODE_ISALNUM(ch); }
static int _npy_char_isspace(Py_UCS4 ch) { return Py_UNICODE_ISSPACE(ch); }

/*
 * Fast path for unary string classification methods (isalpha, isdigit, etc.)
 * on Unicode arrays. Operates directly on raw UCS-4 data to avoid the
 * overhead of creating Python string objects for each element.
 *
 * Consumes a reference to `type` (both on success and error).
 */
static PyObject *
_vec_string_unary_bool_fast(PyArrayObject* char_array, PyArray_Descr* type,
                            int (*classify)(Py_UCS4))
{
    PyArrayIterObject* in_iter = NULL;
    PyArrayObject* result = NULL;

    int itemsize = PyArray_DESCR(char_array)->elsize;
    int num_chars = itemsize / (int)sizeof(npy_ucs4);

    in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
    if (in_iter == NULL) {
        Py_DECREF(type);
        return NULL;
    }

    /* type is consumed by SimpleNewFromDescr */
    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        Py_DECREF(in_iter);
        return NULL;
    }

    npy_bool* out_data = (npy_bool*)PyArray_DATA(result);
    npy_intp i = 0;

    while (PyArray_ITER_NOTDONE(in_iter)) {
        npy_ucs4* chars = (npy_ucs4*)in_iter->dataptr;

        /* Strip trailing null characters to match Python str semantics */
        int len = num_chars;
        while (len > 0 && chars[len - 1] == 0) {
            len--;
        }

        /* All characters must satisfy predicate; empty string is False */
        npy_bool match = (len > 0);
        for (int j = 0; j < len; j++) {
            if (!classify(chars[j])) {
                match = 0;
                break;
            }
        }
        out_data[i] = match;

        PyArray_ITER_NEXT(in_iter);
        i++;
    }

    Py_DECREF(in_iter);
    return (PyObject*)result;
}
```

