static PyObject *
_vec_string_unicode_isalpha(PyArrayObject* char_array, PyArray_Descr* type)
{
    PyArrayObject* result = NULL;
    npy_intp size = PyArray_SIZE(char_array);
    int elsize = PyArray_DESCR(char_array)->elsize;
    int chars_per_element = elsize / (int)sizeof(npy_ucs4);

    result = (PyArrayObject*)PyArray_SimpleNewFromDescr(
            PyArray_NDIM(char_array), PyArray_DIMS(char_array), type);
    if (result == NULL) {
        return NULL;
    }

    npy_bool* out_data = (npy_bool*)PyArray_DATA(result);

    if (PyArray_IS_C_CONTIGUOUS(char_array)) {
        npy_ucs4* in_data = (npy_ucs4*)PyArray_DATA(char_array);

        for (npy_intp i = 0; i < size; i++) {
            npy_ucs4* s = in_data + i * chars_per_element;
            int len = chars_per_element;
            while (len > 0 && s[len-1] == 0) len--;

            npy_bool is_alpha = (len > 0) ? NPY_TRUE : NPY_FALSE;
            for (int j = 0; j < len; j++) {
                if (!Py_UNICODE_ISALPHA(s[j])) {
                    is_alpha = NPY_FALSE;
                    break;
                }
            }
            out_data[i] = is_alpha;
        }
    }
    else {
        // Fall back to iterator for non-contiguous arrays
        PyArrayIterObject* in_iter = (PyArrayIterObject*)PyArray_IterNew((PyObject*)char_array);
        if (in_iter == NULL) {
            Py_DECREF(result);
            return NULL;
        }

        npy_intp i = 0;
        while (PyArray_ITER_NOTDONE(in_iter)) {
            npy_ucs4* s = (npy_ucs4*)in_iter->dataptr;
            int len = chars_per_element;
            while (len > 0 && s[len-1] == 0) len--;

            npy_bool is_alpha = (len > 0) ? NPY_TRUE : NPY_FALSE;
            for (int j = 0; j < len; j++) {
                if (!Py_UNICODE_ISALPHA(s[j])) {
                    is_alpha = NPY_FALSE;
                    break;
                }
            }
            out_data[i] = is_alpha;

            PyArray_ITER_NEXT(in_iter);
            i++;
        }
        Py_DECREF(in_iter);
    }

    return (PyObject*)result;
}
