    if (PyUnicode_CompareWithASCIIString(method_name, "isdigit") == 0)
        return NP_CHAR_METHOD_ISDIGIT;
    if (PyUnicode_CompareWithASCIIString(method_name, "islower") == 0)
        return NP_CHAR_METHOD_ISLOWER;
    if (PyUnicode_CompareWithASCIIString(method_name, "isspace") == 0)
        return NP_CHAR_METHOD_ISSPACE;
    if (PyUnicode_CompareWithASCIIString(method_name, "isupper") == 0)
        return NP_CHAR_METHOD_ISUPPER;
    return NP_CHAR_METHOD_NONE;
