_npy_ascii_isalnum(const char *str, int len) {
    if (len == 0) return 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (!((c >= '0' && c <= '9') || (c >= 'A' && c <= 'Z') || (c >= 'a' && c <= 'z'))) return 0;
    }
    return 1;
}

static inline int
_npy_ascii_isdigit(const char *str, int len) {
    if (len == 0) return 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (!(c >= '0' && c <= '9')) return 0;
    }
    return 1;
}

static inline int
_npy_ascii_islower(const char *str, int len) {
    int cased = 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (c >= 'A' && c <= 'Z') return 0;
        if (c >= 'a' && c <= 'z') cased = 1;
    }
    return cased;
}

static inline int
_npy_ascii_isupper(const char *str, int len) {
    int cased = 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (c >= 'a' && c <= 'z') return 0;
        if (c >= 'A' && c <= 'Z') cased = 1;
    }
    return cased;
}

static inline int
_npy_ascii_isspace(const char *str, int len) {
    if (len == 0) return 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)str[i];
        if (!(c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v')) return 0;
    }
    return 1;
}

